I remember adding this code to make sure that only weapons and offhands could be changed (not armors or accessories) - when using this plugin.
Code:
//We only want the party to be able to change weapons and offhands.
  Window_BattleEquipSlot.prototype.isEnabled = function(index)
  {
     if (! this._actor)
     {
       return false;
     }

     if (index > 1) //0 = weap, 1 = offh.
     {
        return false;
     }
     return this._actor.isEquipChangeOk(index);
  };

